public class Main {
    public static void main(String[] args) {
        TextEditor editor = new TextEditor();
        TextEditorHistory history = new TextEditorHistory();

        editor.write("안녕하세요. ");
        history.save(editor.save()); // 상태 저장

        editor.write("저는 개발자입니다. ");
        history.save(editor.save()); // 상태 저장

